function val(lang,key){return(EXTRA[lang]&&EXTRA[lang][key])||(D[lang]&&D[lang][key])||D.en[key]||key}
function apply(lang){if(!SUPPORTED[lang])lang="en";localStorage.setItem("glow_language",lang);document.documentElement.lang=lang;document.documentElement.dataset.language=lang;const s=document.getElementById("languageSelect");if(s)s.value=lang;Object.values(B).forEach(([sel,key])=>{const el=document.querySelector(sel);if(!el)return;const v=val(lang,key);if(el.tagName==="INPUT"&&el.type==="email"||el.id==="journeyId")el.placeholder=v;else el.innerHTML=v});const orb=ORB[lang]||ORB.en;const orbMap={'.lv3-core-kicker':orb.glow,'.lv3-core-small':orb.six+'<br>'+orb.dims,'.lv3-orb-label.l1':DIM[lang]?.radiance||DIM.en.radiance,'.lv3-orb-label.l2':DIM[lang]?.hydration_appearance||DIM.en.hydration_appearance,'.lv3-orb-label.l3':DIM[lang]?.evenness||DIM.en.evenness,'.lv3-orb-label.l4':DIM[lang]?.texture||DIM.en.texture,'.lv3-orb-label.l5':DIM[lang]?.under_eye||DIM.en.under_eye,'.lv3-orb-label.l6':DIM[lang]?.vitality||DIM.en.vitality};Object.entries(orbMap).forEach(([sel,v])=>{const el=document.querySelector('#s1 '+sel);if(el)el.innerHTML=v});
const landingScoreLabel=document.querySelector('#s1 .lv3-card-top span:first-child');if(landingScoreLabel)landingScoreLabel.textContent=val(lang,'s5.eyebrow');
const landingProfileLabel=document.querySelector('#s1 .lv3-score-band');if(landingProfileLabel)landingProfileLabel.textContent=val(lang,'s5.profile');
const landingDims=['radiance','hydration_appearance','evenness','texture','under_eye','vitality'];document.querySelectorAll('#s1 .lv3-mini-grid span').forEach((el,i)=>{const b=el.querySelector('b');if(!b)return;const score=b.textContent;el.innerHTML='<i></i>'+String(DIM[lang]?.[landingDims[i]]||DIM.en[landingDims[i]]||landingDims[i])+' <b>'+score+'</b>';});
const landingFinalCta=document.querySelector('#s1 .lv3-final .lv3-primary');if(landingFinalCta)landingFinalCta.innerHTML=val(lang,'s1.start');
document.dispatchEvent(new CustomEvent("glow-language-changed",{detail:{language:lang,locale:SUPPORTED[lang].locale}}))}
function preferred(){const saved=localStorage.getItem("glow_language");if(saved&&SUPPORTED[saved])return saved;const b=(navigator.language||"").toLowerCase();if(b.startsWith("fr"))return"fr";if(b.startsWith("es"))return"es";if(b.startsWith("pt"))return"pt";if(b.startsWith("de"))return"de";if(b.startsWith("it"))return"it";return"en"}
function init(){const s=document.getElementById("languageSelect");if(s){s.innerHTML=Object.entries(SUPPORTED).map(([k,v])=>"<option value='"+k+"'>"+v.label+"</option>").join("");s.onchange=()=>apply(s.value)}apply(preferred())}
